package com.bjjj.todo;
import android.content.*;import android.app.job.*;import android.security.keystore.*;import android.util.AtomicFile;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import java.util.concurrent.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;
final class CloudSync {
 static final ExecutorService executor=Executors.newSingleThreadExecutor();static final String URL=BuildConfig.CLOUD_URL,KEY=BuildConfig.CLOUD_KEY;static volatile String error="",email="";static volatile boolean busy;
 static SecretKey key()throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(!ks.containsAlias("bjjj-cloud")){KeyGenerator gen=KeyGenerator.getInstance("AES","AndroidKeyStore");gen.init(new KeyGenParameterSpec.Builder("bjjj-cloud",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());gen.generateKey();}return (SecretKey)ks.getKey("bjjj-cloud",null);}
 static AtomicFile sessionFile(Context c){return new AtomicFile(new File(c.getFilesDir(),"cloud-session.enc"));}
 static JSONObject load(Context c)throws Exception{if(!sessionFile(c).getBaseFile().exists())return null;byte[] data=sessionFile(c).readFully();Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Arrays.copyOfRange(data,0,12)));return new JSONObject(new String(cipher.doFinal(Arrays.copyOfRange(data,12,data.length)),StandardCharsets.UTF_8));}
 static void save(Context c,JSONObject session)throws Exception{if(!session.has("expires_at"))session.put("expires_at",System.currentTimeMillis()/1000+session.optLong("expires_in",3600));Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());byte[] encrypted=cipher.doFinal(session.toString().getBytes(StandardCharsets.UTF_8));AtomicFile file=sessionFile(c);FileOutputStream out=null;try{out=file.startWrite();out.write(cipher.getIV());out.write(encrypted);file.finishWrite(out);}catch(Exception e){if(out!=null)file.failWrite(out);throw e;}}
 static JSONObject request(String path,JSONObject body,String token)throws Exception{HttpURLConnection con=(HttpURLConnection)new java.net.URL(URL+path).openConnection();con.setConnectTimeout(15000);con.setReadTimeout(20000);con.setRequestMethod("POST");con.setRequestProperty("apikey",KEY);con.setRequestProperty("Content-Type","application/json");if(token!=null)con.setRequestProperty("Authorization","Bearer "+token);con.setDoOutput(true);try{try(OutputStream out=con.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}int status=con.getResponseCode();InputStream input=status<400?con.getInputStream():con.getErrorStream();String text=input==null?"{}":readText(input);JSONObject result=text.isEmpty()?new JSONObject():new JSONObject(text);if(status>=400)throw new IOException(result.optString("msg",result.optString("message",result.optString("error_description","同步请求失败 "+status))));return result;}finally{con.disconnect();}}
 static String readText(InputStream input){Scanner scanner=new Scanner(input,"UTF-8").useDelimiter("\\A");return scanner.hasNext()?scanner.next():"{}";}
 static JSONObject session(Context c)throws Exception{JSONObject session=load(c);if(session==null)return null;long expires=session.optLong("expires_at",0);if(expires<System.currentTimeMillis()/1000+90){session=request("/auth/v1/token?grant_type=refresh_token",new JSONObject().put("refresh_token",session.getString("refresh_token")),null);save(c,session);}return session;}
 static void bind(Context c,JSONObject s)throws Exception{synchronized(Store.class){JSONObject root=Store.read(c),cloud=root.optJSONObject("cloud");String uid=s.getJSONObject("user").getString("id");if(cloud!=null&&!cloud.optString("owner").isEmpty()&&!cloud.optString("owner").equals(uid))throw new Exception("本机事项已绑定另一同步账号，不能上传到新账号");if(cloud==null)cloud=new JSONObject().put("base",new JSONObject()).put("conflicts",0);cloud.put("owner",uid);root.put("cloud",cloud);Store.write(c,root);}save(c,s);}
 static JSONObject handle(Context c,String action,JSONObject p)throws Exception{switch(action){case "login":{JSONObject s=request("/auth/v1/token?grant_type=password",p,null);bind(c,s);run(c);break;}case "signup":{JSONObject s=request("/auth/v1/signup",p,null);if(s.has("access_token")){bind(c,s);run(c);}else return new JSONObject().put("message","请在邮箱中确认注册，再使用此同步账号登录。免费个人阶段使用Supabase组织成员邮箱。");break;}case "logout":{JSONObject s=load(c);if(s!=null)request("/auth/v1/logout?scope=local",new JSONObject(),s.getString("access_token"));sessionFile(c).delete();email="";error="";c.getSystemService(JobScheduler.class).cancel(91);c.getSystemService(JobScheduler.class).cancel(92);break;}case "sync":run(c);break;default:throw new Exception("无效的同步操作");}schedule(c);return status(c);}
 static void run(Context c)throws Exception{busy=true;try{JSONObject s=session(c);if(s==null){email="";return;}email=s.getJSONObject("user").optString("email");JSONObject snap; synchronized(Store.class){JSONObject root=Store.read(c);if(!s.getJSONObject("user").getString("id").equals(root.getJSONObject("cloud").optString("owner")))throw new Exception("同步账号与本机数据不一致");snap=SyncProtocol.snapshot(root);}JSONObject response=request("/rest/v1/rpc/sync_tasks",new JSONObject().put("changes",snap.getJSONArray("changes")),s.getString("access_token"));synchronized(Store.class){JSONObject current=Store.read(c);SyncProtocol.apply(current,snap,response);Store.write(c,current);}error="";TodoWidget.updateAll(c);Reminder.schedule(c);}catch(Exception e){error=e.getMessage()==null?"暂时无法同步，离线修改已保留":e.getMessage();throw e;}finally{busy=false;}}
 static JSONObject status(Context c)throws Exception{JSONObject root=Store.read(c),cloud=root.optJSONObject("cloud"),out=new JSONObject();out.put("email",email);out.put("signedIn",sessionFile(c).getBaseFile().exists());out.put("error",error);out.put("busy",busy);out.put("lastSync",cloud==null?"":cloud.optString("lastSync"));out.put("conflicts",cloud==null?0:cloud.optInt("conflicts"));out.put("pending",SyncProtocol.snapshot(root).getJSONArray("changes").length());return out;}
 static void schedule(Context c){if(!sessionFile(c).getBaseFile().exists())return;JobScheduler scheduler=c.getSystemService(JobScheduler.class);ComponentName component=new ComponentName(c,SyncJob.class);if(scheduler.getPendingJob(91)==null)scheduler.schedule(new JobInfo.Builder(91,component).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setPeriodic(15*60*1000).setPersisted(true).build());scheduler.schedule(new JobInfo.Builder(92,component).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setMinimumLatency(1000).setPersisted(true).build());}
}
